// Query a config option using a fuzzed option name; result may be NULL and is treated as read-only
std::string opt = FUZZ_PARAM_STR();
char *val = p11_kit_config_option(module, opt.c_str());
(void)val;
// Keep module for further lifecycle operations

// Generate a buffer and choose a max_length within bounds
std::string buf = FUZZ_PARAM_STR();
size_t maxlen = buf.empty() ? 0 : (size_t)(*FUZZ_PARAM(unsigned int) % buf.size());
size_t n = p11_kit_space_strlen(reinterpret_cast<const unsigned char*>(buf.data()), maxlen);
// Property: result must be <= maxlen
FUZZ_ASSERT(n <= maxlen, "space_strlen exceeded maxlen");

// Generate a buffer and duplicate trimmed space-padded content
std::string buf = FUZZ_PARAM_STR();
