char *dup = p11_kit_space_strdup(reinterpret_cast<const unsigned char*>(buf.data()), maxlen);
// Ownership not specified; do not free. Just ensure returned pointer is either NULL or a valid C-string when non-NULL
if (dup) {
    // Basic sanity: NUL-terminated string should have a strlen within maxlen
    size_t l = strnlen(dup, maxlen + 1);
    FUZZ_ASSERT(l <= maxlen, "space_strdup produced overlong string");
