(void)dup;

// Validate that 'modules' is a p11-kit modules array we previously created
const char *kind = FUZZ_GET_ATTR_STR(modules, "kind");
if (!kind || strcmp(kind, "modules_array") != 0) { FUZZ_BAIL(); }
