// Initialize a single module; success is CKR_OK (0)
CK_RV rv = p11_kit_module_initialize(module);
if (rv == 0) {
    FUZZ_SET_ATTR_INT(module, "initialized", 1);
}
// Keep module for later finalize/release
// Validation: marks initialized only on success; no premature finalize.

// Must only finalize a module that has been initialized
int inited = FUZZ_GET_ATTR_INT(module, "initialized");
if (!inited) { FUZZ_BAIL(); }
CK_RV rv = p11_kit_module_finalize(module);
if (rv == 0) {
    FUZZ_SET_ATTR_INT(module, "finalized", 1);
}
// Keep module so caller can release it
