import os
import random
import struct
from typing import List

# Target: Generate valid arbitrary binary buffers for p11-kit PIN and space-padded helpers.
# The fuzzer stubs use FUZZ_PARAM_STR to obtain a byte string, and enforce non-empty for PIN paths.
# We return bytes that are:
# - Non-empty (to satisfy p11_kit_pin_new requirement in the stub)
# - Of moderate size (<= 2048 preferred by stubs; overall limit 4096 per instructions)
# - Varied content to exercise: printable, mixed binary, space-padded tails, and NULs inside
# - Sometimes long runs of spaces to affect space_strlen/space_strdup trimming behavior

ALPHANUM = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789"
PRINTABLE = ALPHANUM + b" _-:+/@#,.()[]{}"  # include spaces explicitly


def _rand_spaces(rng: random.Random, min_len: int, max_len: int) -> bytes:
    n = rng.randint(min_len, max_len)
    return b" " * n


def _space_padded_field(rng: random.Random, core: bytes, width: int) -> bytes:
    # Trim or right-pad with spaces to exactly width bytes (PKCS#11 style)
    core = core[:width]
    return core + b" " * (width - len(core))


def _mk_space_padded_record(rng: random.Random) -> bytes:
    # Construct a record resembling CK_TOKEN_INFO/CK_SLOT_INFO space-padded fields
    # Sizes per PKCS#11: label[32], manufacturer_id[32], model[16], serial_number[16]
    label = _space_padded_field(rng, _rand_bytes(rng, rng.randint(1, 16)), 32)
    mfg = _space_padded_field(rng, _rand_bytes(rng, rng.randint(1, 16)), 32)
    model = _space_padded_field(rng, _rand_bytes(rng, rng.randint(1, 8)), 16)
    serial = _space_padded_field(rng, _rand_bytes(rng, rng.randint(1, 8)), 16)
    return label + mfg + model + serial


def _rand_bytes(rng: random.Random, n: int) -> bytes:
    # Mix printable and binary, ensure occasional NULs
    out = bytearray()
    for i in range(n):
        t = rng.random()
        if t < 0.6:
            out.append(rng.choice(PRINTABLE))
        elif t < 0.8:
            out.append(rng.randrange(0, 256))
        else:
            # insert NULs or spaces to affect trimming
            out.append(0 if rng.random() < 0.5 else 0x20)
    return bytes(out)


def _pin_candidate(rng: random.Random) -> bytes:
    # Produce a reasonable PIN buffer (non-empty, length up to 2048)
    style = rng.choice(["numeric", "printable", "binary", "spacesuffix", "mix"]) 
    max_len = rng.randint(1, 2048)
    if style == "numeric":
        length = rng.randint(4, min(16, max_len))
        return bytes(rng.choice(b"0123456789") for _ in range(length))
    elif style == "printable":
        length = rng.randint(1, max_len)
        return bytes(rng.choice(PRINTABLE) for _ in range(length))
    elif style == "binary":
        length = rng.randint(1, max_len)
        return _rand_bytes(rng, length)
    elif style == "spacesuffix":
        # Useful for space_strdup/strlen; ensure trailing spaces exist
        core_len = rng.randint(1, max(1, max_len - 1))
        core = _rand_bytes(rng, core_len)
        trail = _rand_spaces(rng, 1, min(64, max_len - core_len))
        return (core + trail)[:max_len]
    else:
        # mix with embedded NULs and trailing spaces
        core_len = rng.randint(1, max_len)
        core = _rand_bytes(rng, core_len)
        if rng.random() < 0.5:
            core += _rand_spaces(rng, 1, min(64, max(1, max_len - len(core))))
        return core[:max_len]


def _compose_buffer(rng: random.Random) -> bytes:
    parts: List[bytes] = []

    # 1) Start with a PIN-like chunk (non-empty)
    parts.append(_pin_candidate(rng))

    # 2) Optionally add a delimiter and another section with many trailing spaces
    if rng.random() < 0.7:
        parts.append(b"\x00")  # embedded NUL
        pad_core = _rand_bytes(rng, rng.randint(4, 64))
        parts.append(pad_core + _rand_spaces(rng, 1, 64))

    # 3) Optionally include a space-padded record block to exercise space_strdup/strlen
    if rng.random() < 0.6:
        parts.append(_mk_space_padded_record(rng))

    # 4) Random filler to diversify content, bounded overall size
    if rng.random() < 0.8:
        parts.append(_rand_bytes(rng, rng.randint(0, 256)))

    buf = b"".join(parts)
    # Ensure non-empty and size cap 4096
    if not buf:
        buf = b"0"
    return buf[:4096]


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Occasionally bias to specific interesting shapes
    mode = rng.choice(["pin_only", "with_spaces", "record", "mixed"])
    if mode == "pin_only":
        buf = _pin_candidate(rng)
    elif mode == "with_spaces":
        core = _pin_candidate(rng)
        buf = core + _rand_spaces(rng, 1, 256)
    elif mode == "record":
        buf = _mk_space_padded_record(rng)
        # prepend a small non-empty prefix to satisfy any strict non-empty expectations uniformly
        if rng.random() < 0.5:
            buf = _pin_candidate(rng)[:16] + b"\x00" + buf
    else:
        buf = _compose_buffer(rng)

    # Final clamp and guarantee non-empty
    if not buf:
        buf = b"x"
    if len(buf) > 4096:
        buf = buf[:4096]
    return buf

import os
import random
import string
from typing import List

# This generator produces interesting, valid C strings (NUL-terminated by the fuzzer harness)
# suited for the p11-kit related stubs that call FUZZ_PARAM_STR(). We focus on PIN-like values,
# pin-source identifiers, module names/paths, URI strings, vendor query keys/values, and generic
# descriptive text. The harness will append a terminating NUL when converting bytes to std::string
#/c_str in C++; here we just return raw bytes content that should be treated as the characters
# before the implicit NUL.

MAX_TOTAL = 4096

PRINTABLE = string.ascii_letters + string.digits + " _-.:/+@#,$%()[]{}=\"'"
HEX = "0123456789abcdef"
BASE64 = string.ascii_letters + string.digits + "+/="

URI_LABELS = [
    "token", "manufacturer", "serial", "model", "object", "type", "id",
    "module-name", "module-path", "pin-value", "pin-source"
]

MODULE_NAMES = [
    "p11-kit-trust", "softhsm", "opensc-pkcs11", "nss", "chil", "gkr"
]

VENDOR_KEYS = [
    "p11-kit-mechanism", "trust-policy", "nss-trust-ssl", "provider", "slot", "app-id"
]

PIN_SOURCES = [
    "file:/tmp/pin.txt", "env:PKCS11_PIN", "stdin", "askpass", "keyring", "memory"
]

DESCRIPTIONS = [
    "login user", "so login", "context specific", "retry", "final try", "change pin"
]

# Builders for different interesting string classes

def rand_printable(r: random.Random, min_len=1, max_len=64) -> str:
    n = r.randint(min_len, max_len)
    return ''.join(r.choice(PRINTABLE) for _ in range(n))

def rand_pin(r: random.Random) -> str:
    # Typical PINs: numeric, alnum, with edge cases min/max length
    choice = r.randint(0, 5)
    if choice == 0:
        n = r.choice([4, 6, 8, 12])
        return ''.join(r.choice(string.digits) for _ in range(n))
    elif choice == 1:
        n = r.choice([1, 2, 32])  # include very short and upper bound
        return ''.join(r.choice(string.digits) for _ in range(n))
    elif choice == 2:
        n = r.randint(4, 32)
        return ''.join(r.choice(string.ascii_letters + string.digits) for _ in range(n))
    elif choice == 3:
        # Include non-printable edge bytes within reasonable ASCII range
        n = r.randint(4, 32)
        data = bytearray()
        for _ in range(n):
            b = r.choice([r.randint(1, 31), r.randint(32, 126)])
            data.append(b)
        return data.decode('latin1')
    elif choice == 4:
        # Hex-like
        n = r.choice([8, 16, 32, 40, 64])
        return ''.join(r.choice(HEX) for _ in range(n))
    else:
        # Base64-like
        n = r.choice([8, 12, 24, 32])
        s = ''.join(r.choice(BASE64) for _ in range(n))
        return s

def rand_pin_source(r: random.Random) -> str:
    c = r.randint(0, 4)
    if c == 0:
        return r.choice(PIN_SOURCES)
    elif c == 1:
        # file path style
        parts = ["/etc", "usr", "local", "var", "home", "tmp"]
        depth = r.randint(1, 4)
        path = "/" + "/".join(r.choice(parts + [rand_printable(r,1,8)]) for _ in range(depth))
        fname = rand_printable(r, 3, 10)
        return f"file:{path}/{fname}.pin"
    elif c == 2:
        # env style
        name = ''.join(r.choice(string.ascii_uppercase + string.digits + "_") for _ in range(r.randint(4, 16)))
        return f"env:{name}"
    elif c == 3:
        return f"helper:{rand_printable(r,3,12)}"
    else:
        return rand_printable(r, 3, 32)

def rand_module_name(r: random.Random) -> str:
    if r.random() < 0.5:
        return r.choice(MODULE_NAMES)
    return rand_printable(r, 3, 32)

def rand_module_path(r: random.Random) -> str:
    # Unix-like shared object path
    base = "/usr/lib/" if r.random() < 0.7 else "/usr/local/lib/"
    name = rand_module_name(r).replace(' ', '-')
    suffix = r.choice([".so", ".dylib", ".dll"])  # cross-platform flavors
    return base + name + suffix

def percent_encode(s: str) -> str:
    out = []
    for ch in s:
        o = ord(ch)
        if (65 <= o <= 90) or (97 <= o <= 122) or (48 <= o <= 57) or ch in "-_.~":
            out.append(ch)
        else:
            out.append("%{:02X}".format(o & 0xFF))
    return ''.join(out)

def rand_pkcs11_uri(r: random.Random) -> str:
    # Build a pkcs11 URI covering common components and vendor queries
    comps = []
    # Core components
    if r.random() < 0.8:
        comps.append(f"token={percent_encode(rand_printable(r,1,16))}")
    if r.random() < 0.6:
        comps.append(f"manufacturer={percent_encode(rand_printable(r,1,16))}")
    if r.random() < 0.6:
        comps.append(f"model={percent_encode(rand_printable(r,1,16))}")
    if r.random() < 0.6:
        comps.append(f"serial={percent_encode(''.join(r.choice(string.digits) for _ in range(r.randint(4,16))))}")
    if r.random() < 0.8:
        comps.append(f"object={percent_encode(rand_printable(r,1,16))}")
    if r.random() < 0.8:
        comps.append(f"type={percent_encode(r.choice(['cert','public','private','secret-key','data']))}")
    if r.random() < 0.5:
        # id as hex bytes
        n = r.randint(1, 8)
        comps.append("id=" + percent_encode(''.join(r.choice(HEX) for _ in range(2*n))))
    # Module fields
    if r.random() < 0.5:
        comps.append("module-name=" + percent_encode(rand_module_name(r)))
    if r.random() < 0.3:
        comps.append("module-path=" + percent_encode(rand_module_path(r)))
    # Authentication helpers
    if r.random() < 0.3:
        comps.append("pin-source=" + percent_encode(rand_pin_source(r)))
    if r.random() < 0.1:
        comps.append("pin-value=" + percent_encode(rand_pin(r)))
    # Vendor queries (query portion)
    qitems = []
    if r.random() < 0.7:
        for _ in range(r.randint(0, 2)):
            key = r.choice(VENDOR_KEYS + [rand_printable(r,3,12)])
            val = rand_printable(r,1,10)
            qitems.append(f"{percent_encode(key)}={percent_encode(val)}")
    uri = "pkcs11:" + ";".join(comps)
    if qitems:
        uri += "?" + "&".join(qitems)
    return uri

def rand_vendor_key(r: random.Random) -> str:
    if r.random() < 0.6:
        return r.choice(VENDOR_KEYS)
    return rand_printable(r, 3, 24)

def rand_description(r: random.Random) -> str:
    base = r.choice(DESCRIPTIONS)
    if r.random() < 0.5:
        base += " (" + rand_printable(r, 3, 12) + ")"
    return base

# Mix of scenarios aligned with stubs using FUZZ_PARAM_STR():
# - PIN strings
# - pin-source strings
# - module names and paths
# - pkcs11 URIs for parse()
# - vendor key/value strings
# - generic descriptions

def build_corpus(r: random.Random) -> List[bytes]:
    items: List[bytes] = []
    # PINs
    for _ in range(6):
        items.append(rand_pin(r).encode('latin1'))
    # Pin sources
    for _ in range(4):
        items.append(rand_pin_source(r).encode('utf-8', 'ignore'))
    # Module names/paths
    for _ in range(3):
        items.append(rand_module_name(r).encode('utf-8', 'ignore'))
    for _ in range(2):
        items.append(rand_module_path(r).encode('utf-8', 'ignore'))
    # PKCS#11 URIs
    for _ in range(6):
        items.append(rand_pkcs11_uri(r).encode('utf-8', 'ignore'))
    # Vendor keys and values
    for _ in range(4):
        items.append(rand_vendor_key(r).encode('utf-8', 'ignore'))
        items.append(rand_printable(r,1,16).encode('utf-8', 'ignore'))
    # Descriptions
    for _ in range(4):
        items.append(rand_description(r).encode('utf-8', 'ignore'))
    # Generic printable and with edge bytes
    for _ in range(6):
        items.append(rand_printable(r,1,64).encode('utf-8', 'ignore'))
        # include some with control chars (not NUL) to exercise parsing
        n = r.randint(4, 24)
        raw = bytearray()
        for _ in range(n):
            raw.append(r.choice([r.randint(1,31), r.randint(32,126)]))
        items.append(bytes(raw))
    return items


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    corpus = build_corpus(r)
    # Choose one item, but occasionally concatenate to exercise longer strings used by parse() or descriptions
    pick = r.choice(corpus)
    if len(pick) < 128 and r.random() < 0.25:
        extra = r.choice(corpus)
        combined = pick + (b";" if pick.startswith(b"pkcs11:") else b" ") + extra
        pick = combined[:1024]
    # Ensure we never exceed the global limit
    return pick[:MAX_TOTAL]
